		step(3050, 3357, 3, ObjectID.ROOFTOPS_FALADOR_HANDHOLDS_START),
		step(3048, 3361, 3, ObjectID.ROOFTOPS_FALADOR_GAP_1),
		step(3041, 3361, 3, ObjectID.ROOFTOPS_FALADOR_GAP_2),
		step(3028, 3354, 3, ObjectID.ROOFTOPS_FALADOR_TIGHTROPE_2),
		step(3020, 3353, 3, ObjectID.ROOFTOPS_FALADOR_TIGHTROPE_3),
		step(3018, 3349, 3, ObjectID.ROOFTOPS_FALADOR_GAP_3),
		step(3014, 3346, 3, ObjectID.ROOFTOPS_FALADOR_LEDGE_1),
		step(3013, 3342, 3, ObjectID.ROOFTOPS_FALADOR_LEDGE_2),
		step(3015, 3334, 3, ObjectID.ROOFTOPS_FALADOR_LEDGE_3A, ObjectID.ROOFTOPS_FALADOR_LEDGE_3B),
		step(3019, 3334, 3, ObjectID.ROOFTOPS_FALADOR_LEDGE_4),
		step(3029, 3334, 0, ObjectID.ROOFTOPS_FALADOR_EDGE)),
	SEERS(2700, 3461, 2729, 3496,
		step(2729, 3491, 3, ObjectID.ROOFTOPS_SEERS_WALLCLIMB),
		step(2713, 3494, 2, ObjectID.ROOFTOPS_SEERS_JUMP),
		step(2710, 3480, 2, ObjectID.ROOFTOPS_SEERS_TIGHTROPE),
		step(2710, 3472, 3, ObjectID.ROOFTOPS_SEERS_JUMP_1),
		step(2702, 3465, 2, ObjectID.ROOFTOPS_SEERS_JUMP_2),
		step(2704, 3464, 0, ObjectID.ROOFTOPS_SEERS_LEAPDOWN)),
	POLLNIVNEACH(3349, 2962, 3369, 3001,
		step(3351, 2964, 1, ObjectID.ROOFTOPS_POLLNIVNEACH_BASKET),
		step(3352, 2973, 1, ObjectID.ROOFTOPS_POLLNIVNEACH_MARKETSTALL),
		step(3360, 2977, 1, ObjectID.ROOFTOPS_POLLNIVNEACH_HANGINGBANNER),
		step(3366, 2976, 1, ObjectID.ROOFTOPS_POLLNIVNEACH_GAP),
		step(3368, 2982, 1, ObjectID.ROOFTOPS_POLLNIVNEACH_TREE),
		step(3365, 2983, 2, ObjectID.ROOFTOPS_POLLNIVNEACH_WALLCLIMB),
		step(3358, 2991, 2, ObjectID.ROOFTOPS_POLLNIVNEACH_MONKEYBARS_START),
		step(3359, 3000, 2, ObjectID.ROOFTOPS_POLLNIVNEACH_TREETOP),
		step(3363, 2998, 0, ObjectID.ROOFTOPS_POLLNIVNEACH_LINE)),
	RELLEKKA(2621, 3654, 2654, 3677,
		step(2625, 3676, 3, ObjectID.ROOFTOPS_RELLEKKA_WALLCLIMB),
		step(2622, 3668, 3, ObjectID.ROOFTOPS_RELLEKKA_GAP_1),
		step(2627, 3654, 3, ObjectID.ROOFTOPS_RELLEKKA_TIGHTROPE_1),
		step(2639, 3653, 3, ObjectID.ROOFTOPS_RELLEKKA_GAP_2),
		step(2643, 3657, 3, ObjectID.ROOFTOPS_RELLEKKA_GAP_3),
		step(2655, 3670, 3, ObjectID.ROOFTOPS_RELLEKKA_TIGHTROPE_3),
		step(2653, 3676, 0, ObjectID.ROOFTOPS_RELLEKKA_DROPOFF)),
	ARDOUGNE(2651, 3296, 2673, 3318,
		step(2671, 3299, 3, ObjectID.ROOFTOPS_ARDY_WALLCLIMB),
		step(2665, 3318, 3, ObjectID.ROOFTOPS_ARDY_JUMP),
		step(2656, 3318, 3, ObjectID.ROOFTOPS_ARDY_PLANK),
		step(2653, 3314, 3, ObjectID.ROOFTOPS_ARDY_JUMP_2),
		step(2651, 3309, 3, ObjectID.ROOFTOPS_ARDY_JUMP_3),
		step(2656, 3297, 3, ObjectID.ROOFTOPS_ARDY_WALLCROSSING),
		step(2668, 3297, 0, ObjectID.ROOFTOPS_ARDY_JUMP_4));

	// How far outside its bounds, in tiles, still counts as on the course.
	private static final int MARGIN = 8;
	private static final int[][] STEPS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

	final RooftopObstacle[] obstacles;
	private final int minX, minY, maxX, maxY;

	Course(int minX, int minY, int maxX, int maxY, RooftopObstacle... obstacles)
	{
		this.minX = minX;
		this.minY = minY;
		this.maxX = maxX;
		this.maxY = maxY;
		this.obstacles = obstacles;
	}

	private static RooftopObstacle step(int x, int y, int plane, int... objectIds)
	{
		return new RooftopObstacle(new WorldPoint(x, y, plane), objectIds);
	}

	/** The course the tile is on or beside, or null. */
	static Course near(WorldPoint tile)
	{
		return Arrays.stream(values()).filter(course -> course.isNear(tile)).findFirst().orElse(null);
	}

	static boolean isObstacle(int objectId)
	{
		return Arrays.stream(values()).anyMatch(course -> course.indexOf(objectId) >= 0);
	}

	boolean isNear(WorldPoint tile)
	{
		return tile.getX() >= minX - MARGIN && tile.getX() <= maxX + MARGIN
			&& tile.getY() >= minY - MARGIN && tile.getY() <= maxY + MARGIN;
	}

	/** The object's place in the lap, or -1. */
	int indexOf(int objectId)
	{
		for (int index = 0; index < obstacles.length; index++)
		{
			if (obstacles[index].is(objectId))
			{
				return index;
			}
		}
		return -1;
	}

	/**
	 * The obstacle whose landing tile can be walked to from the given tile, or -1. Roofs are only joined by
	 * obstacles, so that is the one the player last completed.
	 */
	int lastCompletedAt(WorldPoint from, BiPredicate<WorldPoint, WorldPoint> canStep)
	{
		Set<WorldPoint> seen = new HashSet<>();
		Queue<WorldPoint> reached = new ArrayDeque<>();
		seen.add(from);
		reached.add(from);
		while (!reached.isEmpty())
		{
			WorldPoint tile = reached.remove();
			int index = RooftopObstacle.landingOn(obstacles, tile);
			if (index >= 0)
			{
				return index;
			}
			for (int[] step : STEPS)
			{
				WorldPoint next = tile.dx(step[0]).dy(step[1]);
				if (isNear(next) && canStep.test(tile, next) && seen.add(next))
				{
					reached.add(next);
				}
			}
		}
		return -1;
	}
}

package com.rooftopobstaclepreview;

import net.runelite.api.coords.WorldPoint;

/** Which obstacle the player last completed, whether they have started the next, and what they clicked since. */
final class CourseProgress
{
	// A minute of game ticks: how long the whole course stays on show once the player does something after a lap.
	private static final int LINGER_TICKS = 100;

	private final RooftopObstacle[] obstacles;
	private int landedOn;
	private int lastClicked = -1;
	private boolean pendingLanding;
	// Seen off any obstacle since landing, so the next animation is not the tail of the one just done.
	private boolean settled;
	// Came off an obstacle, by landing or falling, and the tick has yet to take that in.
	private boolean cameOff;
	private boolean nextBecameReady;
	private boolean left;
	// Clicked anywhere since the last landing or fall. Until then the player may be AFK, so the minute waits.
	private boolean actedSinceLanding;
	private int ticksOffLap = LINGER_TICKS;

	// A lap starts where the last obstacle lands the player.
	CourseProgress(RooftopObstacle[] obstacles)
	{
		this.obstacles = obstacles;
		landedOn = obstacles.length - 1;
	}

	/** For a player first seen part-way round. */
	void resumeAfter(int index)
	{
		landedOn = index;
	}

	/**
	 * A click that sends the player somewhere: the obstacle's index, or -1 for anywhere else. The game ignores clicks
	 * from the moment an obstacle starts until its xp drops, even once the player is standing on its landing tile.
	 */
	void clicked(int index)
	{
		if (left && !pendingLanding)
		{
			return;
		}
		lastClicked = index;
		actedSinceLanding = true;
	}

	// The game takes clicks from the xp drop, so one before the tick that registers the landing is acting after it.
	void xpDrop()
	{
		pendingLanding = true;
		actedSinceLanding = false;
	}

	/** A failed obstacle drops the player off the course, so the lap starts over. */
	void fell()
	{
		landedOn = obstacles.length - 1;
		lastClicked = -1;
		pendingLanding = false;
		settled = false;
		cameOff = true;
		left = false;
		actedSinceLanding = false;
	}

	/** Call once per game tick with the player's tile and whether they are animating, as on an obstacle. */
	void tick(WorldPoint player, boolean animating)
	{
		if (pendingLanding)
		{
			landedOn = landingIndex(player);
			pendingLanding = false;
			settled = false;
			cameOff = true;
			left = false;
		}
		nextBecameReady = cameOff && !actedSinceLanding;
		cameOff = false;
		// Setting off is starting the next obstacle after clicking it. Walking up to it is not, since another
		// click can still call that off.
		if (!animating)
		{
			settled = true;
		}
		else if (settled && !left && lastClicked == (landedOn + 1) % obstacles.length)
		{
			left = true;
		}
		if (onLap())
		{
			ticksOffLap = 0;
		}
		else if (actedSinceLanding)
		{
			ticksOffLap = Math.min(ticksOffLap + 1, LINGER_TICKS);
		}
	}

	/**
	 * Whether this is the first tick the game would take a click on the next obstacle since the last one landed or
	 * dropped the player, and they have yet to click anything: the earliest an idle notification can be acted on.
	 * That is the xp drop, while the obstacle's animation may still be finishing.
	 */
	boolean nextBecameReady()
	{
		return nextBecameReady;
	}

	/**
	 * Whether to show every obstacle rather than just the first: on a lap, or within a minute of first doing
	 * something after finishing or falling off one.
	 */
	boolean showsWholeCourse()
	{
		return onLap() || ticksOffLap < LINGER_TICKS;
	}

	// Part-way round, or setting out with a click on the first obstacle.
	private boolean onLap()
	{
		return landedOn != obstacles.length - 1 || left || lastClicked == 0;
	}

	/**
	 * The obstacle the player is heading for but has not started, when they are off the tile it is clicked from, so
	 * its box belongs on its real clickbox; or -1. A click elsewhere can still call it off and make it next again.
	 */
	int liveIndex(WorldPoint player)
	{
		return left || player.equals(obstacles[landedOn].landing) ? -1 : (landedOn + 1) % obstacles.length;
	}

	/**
	 * Whether a click on the next obstacle would be acted on now: the one before it has landed the player and they are
	 * not on their way to another. Mid-obstacle the game ignores the click, and before that it would call off the
	 * obstacle they are heading for.
	 */
	boolean nextIsReady()
	{
		return !left && lastClicked != (landedOn + 1) % obstacles.length;
	}

	/**
	 * The index of the obstacle that many clicks away: 0 is the next to click, the last is the one just done. Clicking
	 * the next obstacle moves on at once, on the bet that the click is not called off.
	 */
	int indexClicksAway(int clicks)
	{
		int unstarted = (landedOn + (left ? 1 : 0) + 1) % obstacles.length;
		return (unstarted + (lastClicked == unstarted ? 1 : 0) + clicks) % obstacles.length;
	}

	private int landingIndex(WorldPoint player)
	{
		int index = RooftopObstacle.landingOn(obstacles, player);
		if (index >= 0)
		{
			return index;
		}
		// Off every landing tile, the obstacle clicked before setting off, or else the one next in lap order.
		return lastClicked < 0 ? (landedOn + 1) % obstacles.length : lastClicked;
	}
}

package com.rooftopobstaclepreview;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws each obstacle's clickbox where it will be on screen when it is the next to click: as seen from the tile the
 * obstacle before it lands the player on. The camera orbits a focal point above the player, so that view is today's
 * camera looking at the obstacle's model shifted by (focal point now - focal point then).
 */
class GhostClickboxOverlay extends Overlay
{
	private static final int STEADY_FRAMES = 15;
	private static final int MAX_OFF_AXIS = 16;
	// The follow height grows with the log of the zoom: measured from zoom 242 to 1604, it fits to within a unit.
	private static final double FOLLOW_PER_LOG_SCALE = 35.0;
	private static final float BLUE_HUE = 240f / 360f;
	private static final int FILL_ALPHA = 90;
	private static final int BORDER_ALPHA = 150;
	private static final Color SHARED_TRIM = new Color(255, 200, 0);
	private static final Color READY_TRIM = new Color(255, 215, 0);
	private static final int SQUIRREL_SIZE = 30;
	// The squirrel pet's icon faces left.
	private static final boolean SQUIRREL_FACES_LEFT = true;

	private final Client client;
	private final ObstacleTracker tracker;
	private final RooftopObstaclePreviewConfig config;
	private final ItemManager itemManager;
	// The squirrel pet's item icon, the same with its transparent margins cut off once it has loaded, and which way
	// the squirrel faces after where it was last drawn.
	private BufferedImage squirrelIcon;
	private BufferedImage squirrel;
	private boolean squirrelFacingLeft = SQUIRREL_FACES_LEFT;
	private double squirrelWasX = Double.NaN;

	// The focal point is distanceRatio * (600 + 3 * pitch) ahead of the camera and FOLLOW_PER_LOG_SCALE * ln(zoom) +
	// followOffset above the player's ground. Client.getCameraFocalPoint only works in free-camera mode, so both are
	// measured whenever the player and camera are at rest.
	private double distanceRatio = 1.25;
	private double followOffset = -174.7;
	private double[] lastCamera = new double[3];
	private int steadyFrames;
	private boolean measured;

	GhostClickboxOverlay(Client client, ObstacleTracker tracker, RooftopObstaclePreviewConfig config,
		ItemManager itemManager)
	{
		this.client = client;
		this.tracker = tracker;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Player player = client.getLocalPlayer();
		Course course = tracker.getCourse();
		if (player == null || course == null || tracker.getObjects().isEmpty())
		{
			return null;
		}

		double pitch = client.getCameraFpPitch();
		double yaw = client.getCameraFpYaw();
		double[] forward = {-Math.sin(yaw) * Math.cos(pitch), Math.cos(yaw) * Math.cos(pitch), Math.sin(pitch)};
		double[] camera = {client.getCameraFpX(), client.getCameraFpY(), client.getCameraFpZ()};
		double formulaDistance = 600 + 3 * pitch / Perspective.UNIT;

		boolean atRest = cameraAtRest(camera) && tracker.getTicksStill() >= 2;
		if (atRest && !measured)
		{
			measureCamera(camera, forward, formulaDistance, player.getLocalLocation());
		}
		measured = atRest;

		double distance = distanceRatio * formulaDistance;
		double[] focus = new double[3];
		Arrays.setAll(focus, axis -> camera[axis] + distance * forward[axis]);

		int count = course.obstacles.length;
		int next = tracker.indexClicksAway(0);
		int live = tracker.liveIndex();
		// Away from a lap, as when just passing through, only the first obstacle shows.
		boolean wholeCourse = tracker.showsWholeCourse();
		Area[] boxes = new Area[count];
		Arrays.setAll(boxes, index -> new Area());
		for (TileObject object : tracker.getObjects())
		{
			int index = course.indexOf(object.getId());
			if (index < 0 || !wholeCourse && index != next)
			{
				continue;
			}
			// Off the last landing tile, the obstacle being headed for is clicked from where the player stands until
			// they start it, so its box goes on the real clickbox.
			int[] shift = index == live ? new int[3]
				: shift(course.obstacles[(index + count - 1) % count].landing, focus);
			if (shift != null)
			{
				addClickbox(boxes[index], object, shift[0], shift[1], shift[2]);
			}
		}

		// Under the boxes, so the red box it rides into stays on top.
		if (config.squirrel())
		{
			drawSquirrel(graphics, course, next);
		}

		// Coolest first, so the next box ends up on top.
		graphics.setStroke(new BasicStroke(1));
		for (int away = count - 1; away >= 0; away--)
		{
			Area box = boxes[tracker.indexClicksAway(away)];
			Color fill = orderColour(away, count);
			graphics.setColor(fill);
			graphics.fill(box);
			graphics.setColor(new Color(fill.getRed(), fill.getGreen(), fill.getBlue(), BORDER_ALPHA));
			graphics.draw(box);
		}

		// A gold border on the next box once a click on it would be acted on.
		if (tracker.nextIsReady())
		{
			graphics.setColor(READY_TRIM);
			graphics.setStroke(new BasicStroke(2));
			graphics.draw(boxes[next]);
		}

		// Gold outline where the next two or more boxes overlap: one mouse position serves all of those clicks.
		graphics.setColor(SHARED_TRIM);
		graphics.setStroke(new BasicStroke(2));
		Area shared = boxes[next];
		for (int away = 1; away < count && !shared.isEmpty(); away++)
		{
			shared.intersect(boxes[tracker.indexClicksAway(away)]);
			graphics.draw(shared);
		}
		return null;
	}

	/**
	 * The squirrel rides the next obstacle's clickbox where it really is on screen, which slides into the red box as the
	 * player heads for the tile it is clicked from, and faces the way it moves.
	 */
	private void drawSquirrel(Graphics2D graphics, Course course, int next)
	{
		if (squirrelIcon == null)
		{
			squirrelIcon = itemManager.getImage(ItemID.SKILLPETAGILITY);
		}
		squirrel = squirrel != null ? squirrel : trim(squirrelIcon);
		Area real = new Area();
		for (TileObject object : tracker.getObjects())
		{
			if (course.indexOf(object.getId()) == next)
			{
				addClickbox(real, object, 0, 0, 0);
			}
		}
		if (squirrel == null || real.isEmpty())
		{
			return;
		}
		Rectangle bounds = real.getBounds();
		if (Math.abs(bounds.getCenterX() - squirrelWasX) >= 1)
		{
			squirrelFacingLeft = bounds.getCenterX() < squirrelWasX;
		}
		squirrelWasX = bounds.getCenterX();
		int width = SQUIRREL_SIZE * squirrel.getWidth() / squirrel.getHeight();
		int x = (int) Math.round(bounds.getCenterX() - width / 2.0);
		int y = (int) Math.round(bounds.getCenterY() - SQUIRREL_SIZE / 2.0);
		if (squirrelFacingLeft == SQUIRREL_FACES_LEFT)
		{
			graphics.drawImage(squirrel, x, y, width, SQUIRREL_SIZE, null);
		}
		else
		{
			graphics.drawImage(squirrel, x + width, y, -width, SQUIRREL_SIZE, null);
		}
	}

	/** The icon cut down to its drawn pixels, or null while it is still loading and has none. */
	private static BufferedImage trim(BufferedImage icon)
	{
		int minX = icon.getWidth();
		int minY = icon.getHeight();
		int maxX = -1;
		int maxY = -1;
		for (int y = 0; y < icon.getHeight(); y++)
		{
			for (int x = 0; x < icon.getWidth(); x++)
			{
				if ((icon.getRGB(x, y) >>> 24) != 0)
				{
					minX = Math.min(minX, x);
					minY = Math.min(minY, y);
					maxX = Math.max(maxX, x);
					maxY = Math.max(maxY, y);
				}
			}
		}
		return maxX < 0 ? null : icon.getSubimage(minX, minY, maxX - minX + 1, maxY - minY + 1);
	}

	/** Red for the obstacle to click next, through orange, green and cyan to blue for the one just done. */
	static Color orderColour(int clicksAway, int count)
	{
		Color colour = Color.getHSBColor(count <= 1 ? 0 : BLUE_HUE * clicksAway / (count - 1), 1, 1);
		return new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), FILL_ALPHA);
	}

	/** How far the focal point is from where it will be with the player on the tile, or null if that is off the map. */
	private int[] shift(WorldPoint tile, double[] focus)
	{
		double[] then = focalPoint(tile);
		return then == null ? null : new int[]{(int) Math.round(focus[0] - then[0]),
			(int) Math.round(focus[1] - then[1]), (int) Math.round(focus[2] - then[2])};
	}

	/** Where the camera's focal point will be with the player on the tile, or null if that is off the map. */
	private double[] focalPoint(WorldPoint tile)
	{
		// Not the WorldPoint overload, which returns null for a tile on another plane than the player's.
		LocalPoint local = LocalPoint.fromWorld(client.getTopLevelWorldView(), tile.getX(), tile.getY());
		return local == null ? null
			: new double[]{local.getX(), local.getY(), groundHeight(local, tile.getPlane()) - followHeight()};
	}

	/** Adds the object's clickbox as if it stood (dx, dy, dz) local units from where it is. */
	private void addClickbox(Area box, TileObject object, int dx, int dy, int dz)
	{
		int x = object.getX() + dx;
		int y = object.getY() + dy;
		int z = object.getZ() + dz;
		if (object instanceof GameObject)
		{
			GameObject gameObject = (GameObject) object;
			add(box, object, gameObject.getRenderable(), gameObject.getModelOrientation(), x, y, z);
		}
		else if (object instanceof WallObject)
		{
			add(box, object, ((WallObject) object).getRenderable1(), 0, x, y, z);
			add(box, object, ((WallObject) object).getRenderable2(), 0, x, y, z);
		}
		else if (object instanceof DecorativeObject)
		{
			DecorativeObject decoration = (DecorativeObject) object;
			add(box, object, decoration.getRenderable(), 0, x + decoration.getXOffset(), y + decoration.getYOffset(), z);
			add(box, object, decoration.getRenderable2(), 0, x, y, z);
		}
		else if (object instanceof GroundObject)
		{
			add(box, object, ((GroundObject) object).getRenderable(), 0, x, y, z);
		}
	}

	private void add(Area box, TileObject object, Renderable renderable, int orientation, int x, int y, int z)
	{
		if (renderable == null)
		{
			return;
		}
		Model model = renderable instanceof Model ? (Model) renderable : renderable.getModel();
		Shape clickbox = Perspective.getClickbox(client, object.getWorldView(), model, orientation, x, y, z);
		if (clickbox != null)
		{
			box.add(new Area(clickbox));
		}
	}

	private boolean cameraAtRest(double[] camera)
	{
		boolean moved = false;
		for (int axis = 0; axis < 3; axis++)
		{
			moved |= Math.abs(camera[axis] - lastCamera[axis]) > 0.01;
		}
		lastCamera = camera;
		steadyFrames = moved ? 0 : steadyFrames + 1;
		return steadyFrames >= STEADY_FRAMES;
	}

	// At rest the camera's axis passes over the player: how far along gives the camera distance, and the height
	// there gives the follow height.
	private void measureCamera(double[] camera, double[] forward, double formulaDistance, LocalPoint at)
	{
		int ground = groundHeight(at, client.getTopLevelWorldView().getPlane());
		double along = ((at.getX() - camera[0]) * forward[0] + (at.getY() - camera[1]) * forward[1])
			/ (forward[0] * forward[0] + forward[1] * forward[1]);
		double offAxis = Math.hypot(camera[0] + along * forward[0] - at.getX(), camera[1] + along * forward[1] - at.getY());
		double ratio = along / formulaDistance;
		double follow = ground - (camera[2] + along * forward[2]);
		if (offAxis <= MAX_OFF_AXIS && ratio > 0.5 && ratio < 3 && follow > 0 && follow < 300)
		{
			distanceRatio = ratio;
			followOffset += 0.5 * (follow - followHeight());
		}
	}

	// The camera follows the highest ground under the player's footprint: its centre and corners, which on a slope is
	// above the tile's centre. Perspective.getFootprintTileHeight samples the ground differently, ending up 11 units
	// higher than the camera on Canifis's sloped last landing.
	private int groundHeight(LocalPoint point, int plane)
	{
		Player player = client.getLocalPlayer();
		int half = player == null ? 0 : player.getFootprintSize() / 2;
		int height = Perspective.getTileHeight(client, point, plane);
		for (int dx = -half; dx <= half; dx += 2 * Math.max(half, 1))
		{
			for (int dy = -half; dy <= half; dy += 2 * Math.max(half, 1))
			{
				height = Math.min(height, Perspective.getTileHeight(client, point.plus(dx, dy), plane));
			}
		}
		return height;
	}

	/** How far above the player's ground the camera's focal point is at today's zoom. */
	private double followHeight()
	{
		return FOLLOW_PER_LOG_SCALE * Math.log(client.getScale()) + followOffset;
	}
}

package com.rooftopobstaclepreview;

import com.google.common.collect.Sets;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.DecorativeObjectDespawned;
import net.runelite.api.events.DecorativeObjectSpawned;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GroundObjectDespawned;
import net.runelite.api.events.GroundObjectSpawned;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.WallObjectDespawned;
import net.runelite.api.events.WallObjectSpawned;
import net.runelite.client.Notifier;
import net.runelite.client.eventbus.Subscribe;

/** Tracks the course the player is on, its obstacle objects and the player's progress round it. */
@RequiredArgsConstructor
class ObstacleTracker
{
	// Clicks that send the player somewhere, so call off heading for an obstacle; only the object options are on one.
	private static final Set<MenuAction> SENDS_PLAYER = Sets.union(
		EnumSet.range(MenuAction.ITEM_USE_ON_GAME_OBJECT, MenuAction.WALK),
		EnumSet.range(MenuAction.PLAYER_FIRST_OPTION, MenuAction.PLAYER_EIGHTH_OPTION));
	private static final Set<MenuAction> OBJECT_OPTIONS =
		EnumSet.range(MenuAction.GAME_OBJECT_FIRST_OPTION, MenuAction.GAME_OBJECT_FIFTH_OPTION);

	private final Client client;
	private final Notifier notifier;
	private final RooftopObstaclePreviewConfig config;
	@Getter
	private final Set<TileObject> objects = new HashSet<>();
	@Getter
	private Course course;
	// Game ticks the player has stayed on the same tile.
	@Getter
	private int ticksStill;
	private CourseProgress progress;
	private WorldPoint lastTile;
	private int agilityXp = -1;

	int indexClicksAway(int clicks)
	{
		return progress.indexClicksAway(clicks);
	}

	int liveIndex()
	{
		return progress.liveIndex(lastTile);
	}

	boolean nextIsReady()
	{
		return progress.nextIsReady();
	}

	boolean showsWholeCourse()
	{
		return progress.showsWholeCourse();
	}

	/** Picks up obstacles already in the scene when the plugin is switched on; call on the client thread. */
	void scan()
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (client.getGameState() != GameState.LOGGED_IN || worldView == null)
		{
			return;
		}
		for (Tile[][] plane : worldView.getScene().getTiles())
		{
			for (Tile[] column : plane)
			{
				for (Tile tile : column)
				{
					if (tile == null)
					{
						continue;
					}
					for (GameObject gameObject : tile.getGameObjects())
					{
						track(gameObject);
					}
					track(tile.getWallObject());
					track(tile.getDecorativeObject());
					track(tile.getGroundObject());
				}
			}
		}
	}

	private void track(TileObject object)
	{
		if (object != null && Course.isObstacle(object.getId()))
		{
			objects.add(object);
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		track(event.getGameObject());
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		track(event.getWallObject());
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		track(event.getDecorativeObject());
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		track(event.getGroundObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		objects.remove(event.getGameObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		objects.remove(event.getWallObject());
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		objects.remove(event.getDecorativeObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		objects.remove(event.getGroundObject());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// A map load discards every object; they spawn again afterwards.
		if (event.getGameState() == GameState.LOADING)
		{
			objects.clear();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		MenuAction action = event.getMenuAction();
		if (progress != null && SENDS_PLAYER.contains(action))
		{
			progress.clicked(OBJECT_OPTIONS.contains(action) ? course.indexOf(event.getId()) : -1);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.AGILITY)
		{
			return;
		}
		int before = agilityXp;
		agilityXp = event.getXp();
		if (progress != null && before >= 0 && agilityXp > before)
		{
			progress.xpDrop();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (progress != null && event.getActor() == client.getLocalPlayer())
		{
			progress.fell();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		WorldPoint at = player.getWorldLocation();
		ticksStill = at.equals(lastTile) ? ticksStill + 1 : 0;
		lastTile = at;

		Course near = Course.near(at);
		if (near != course)
		{
			course = near;
			progress = near == null ? null : start(near, at);
		}
		if (progress != null)
		{
			progress.tick(at, player.getAnimation() != -1);
			if (progress.nextBecameReady())
			{
				notifier.notify(config.idleNotification(), "You are now idle!");
			}
		}
	}

	// A player first seen on a roof, as after logging in, is part-way round. On the ground the lap has yet to start,
	// which is how progress begins anyway.
	private CourseProgress start(Course on, WorldPoint at)
	{
		CourseProgress started = new CourseProgress(on.obstacles);
		WorldView worldView = client.getTopLevelWorldView();
		int completed = at.getPlane() == 0 ? -1 : on.lastCompletedAt(at, (from, to) ->
			WorldPoint.isInScene(worldView, to.getX(), to.getY())
				&& from.toWorldArea().canTravelInDirection(worldView, to.getX() - from.getX(), to.getY() - from.getY()));
		if (completed >= 0)
		{
			started.resumeAfter(completed);
		}
		return started;
	}
}

package com.rooftopobstaclepreview;

import com.google.common.primitives.Ints;
import net.runelite.api.coords.WorldPoint;

final class RooftopObstacle
{
	// Where the player stands when the obstacle's xp drops.
	final WorldPoint landing;
	private final int[] objectIds;

	RooftopObstacle(WorldPoint landing, int... objectIds)
	{
		this.landing = landing;
		this.objectIds = objectIds;
	}

	boolean is(int objectId)
	{
		return Ints.contains(objectIds, objectId);
	}

	/** The index of the obstacle that lands on the tile, or -1. */
	static int landingOn(RooftopObstacle[] obstacles, WorldPoint tile)
	{
		for (int index = 0; index < obstacles.length; index++)
		{
			if (obstacles[index].landing.equals(tile))
			{
				return index;
			}
		}
		return -1;
	}
}

