package com.rooftopobstaclepreview;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Rooftop Obstacle Preview",
	description = "Shows where each rooftop obstacle's clickbox will be when it is your next click, coloured by click order",
	tags = {"agility", "rooftop", "clickbox", "overlay", "course"}
)
public class RooftopObstaclePreviewPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventBus eventBus;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RooftopObstaclePreviewConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Notifier notifier;

	private ObstacleTracker tracker;
	private GhostClickboxOverlay overlay;

	@Override
	protected void startUp()
	{
		tracker = new ObstacleTracker(client, notifier, config);
		overlay = new GhostClickboxOverlay(client, tracker, config, itemManager);
		eventBus.register(tracker);
		clientThread.invoke(tracker::scan);
		overlayManager.add(overlay);
	}

	@Provides
	RooftopObstaclePreviewConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RooftopObstaclePreviewConfig.class);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		eventBus.unregister(tracker);
	}
}

package com.rooftopobstaclepreview;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class CourseProgressTest
{
	// Three obstacles: 0 lands on A, 1 on B and the last on C, where a lap starts.
	private static final WorldPoint A = new WorldPoint(10, 10, 3);
	private static final WorldPoint B = new WorldPoint(30, 20, 3);
	private static final WorldPoint C = new WorldPoint(40, 40, 0);

	private final CourseProgress progress = new CourseProgress(new RooftopObstacle[]{
		new RooftopObstacle(A, 1), new RooftopObstacle(B, 2), new RooftopObstacle(C, 3)});

	@Test
	public void lapStartsAtTheFirstObstacle()
	{
		walk(C);
		assertEquals(0, next());
		assertEquals(-1, progress.liveIndex(C));
	}

	@Test
	public void clickingTheNextObstacleMovesOnAtOnce()
	{
		walk(C);
		progress.clicked(0);
		assertEquals(1, next());
		assertEquals(0, progress.indexClicksAway(2));
	}

	@Test
	public void boxStaysLiveUntilTheObstacleStarts()
	{
		walk(C);
		progress.clicked(0);
		walk(C.dx(1));
		walk(C.dx(2));
		assertEquals(1, next());
		assertEquals(0, progress.liveIndex(C.dx(2)));

		animate(C.dx(3));
		assertEquals(1, next());
		assertEquals(-1, progress.liveIndex(C.dx(3)));
	}

	@Test
	public void callingOffTheClickMakesItNextAgain()
	{
		walk(C);
		progress.clicked(0);
		walk(C.dx(1));
		progress.clicked(-1);
		assertEquals(0, next());
		walk(C.dx(2));
		assertEquals(0, progress.liveIndex(C.dx(2)));

		// Nor is an animation after that the obstacle.
		animate(C.dx(2));
		assertEquals(0, next());
		assertEquals(0, progress.liveIndex(C.dx(2)));

		progress.clicked(0);
		assertEquals(1, next());
		walk(C.dx(3));
		animate(C.dx(4));
		assertEquals(1, next());
		assertEquals(-1, progress.liveIndex(C.dx(4)));
	}

	@Test
	public void clickingAnotherObstacleCallsOffTheClick()
	{
		walk(C);
		progress.clicked(0);
		walk(C.dx(1));
		progress.clicked(2);
		assertEquals(0, next());
		animate(C.dx(2));
		assertEquals(0, next());
		assertEquals(0, progress.liveIndex(C.dx(2)));
	}

	@Test
	public void walkingOffWithoutClickingKeepsTheNextBoxLive()
	{
		walk(C);
		walk(C.dx(1));
		assertEquals(0, next());
		assertEquals(0, progress.liveIndex(C.dx(1)));
	}

	@Test
	public void clicksMidObstacleAreIgnored()
	{
		walk(C);
		progress.clicked(0);
		animate(C.dx(1));
		animate(A);
		progress.clicked(1);
		assertEquals(1, next());

		// Nor does this obstacle's animation still finishing on landing start the next.
		land(A);
		animate(A);
		walk(A);
		assertEquals(1, next());
		assertEquals(-1, progress.liveIndex(A));

		progress.clicked(1);
		assertEquals(2, next());
		walk(A.dy(1));
		assertEquals(1, progress.liveIndex(A.dy(1)));
		animate(A.dy(1));
		assertEquals(2, next());
		assertEquals(-1, progress.liveIndex(A.dy(1)));
	}

	@Test
	public void nextIsReadyOnceTheObstacleBeforeItHasLanded()
	{
		walk(C);
		assertTrue(progress.nextIsReady());

		progress.clicked(0);
		assertFalse(progress.nextIsReady());
		walk(C.dx(1));
		animate(C.dx(2));
		assertFalse(progress.nextIsReady());

		land(A);
		assertTrue(progress.nextIsReady());

		// Calling off the walk to it makes the obstacle it was for next, and ready.
		progress.clicked(1);
		assertFalse(progress.nextIsReady());
		progress.clicked(-1);
		assertTrue(progress.nextIsReady());
	}

	@Test
	public void clickingOnTheXpDropCounts()
	{
		walk(C);
		progress.clicked(0);
		animate(C.dx(1));
		progress.xpDrop();
		progress.clicked(1);
		animate(A);
		assertEquals(2, next());
	}

	@Test
	public void landingTileIdentifiesTheObstacle()
	{
		walk(C);
		land(B);
		assertEquals(2, next());
	}

	@Test
	public void unknownLandingTileFollowsLapOrder()
	{
		walk(C);
		land(A.dx(1));
		assertEquals(1, next());
		assertEquals(1, progress.liveIndex(A.dx(1)));
		assertEquals(-1, progress.liveIndex(A));
	}

	@Test
	public void clickOnAnotherObstacleOverridesLapOrder()
	{
		walk(B);
		progress.clicked(2);
		land(C.dx(1));
		assertEquals(0, next());
	}

	@Test
	public void ignoredClickMidObstacleKeepsLapOrder()
	{
		walk(C);
		progress.clicked(0);
		animate(C.dx(1));
		progress.clicked(2);
		land(A.dx(1));
		assertEquals(1, next());
		assertEquals(0, progress.indexClicksAway(2));
	}

	@Test
	public void reachingTheLandingTileATickLateIsNotStarting()
	{
		walk(C);
		land(A.dy(-1));
		progress.clicked(1);
		animate(A);
		walk(A.dy(1));
		assertEquals(1, progress.liveIndex(A.dy(1)));

		animate(A.dy(1));
		assertEquals(-1, progress.liveIndex(A.dy(1)));
	}

	@Test
	public void lastObstacleWrapsToTheFirst()
	{
		walk(B);
		land(C);
		assertEquals(0, next());

		progress.clicked(0);
		assertEquals(1, next());
		walk(C.dx(1));
		animate(C.dx(1));
		assertEquals(1, next());
	}

	@Test
	public void fallRestartsTheLap()
	{
		walk(C);
		land(A);
		progress.clicked(1);

		WorldPoint fallen = new WorldPoint(5, 5, 0);
		progress.fell();
		animate(fallen);
		assertEquals(0, next());
		assertEquals(0, progress.liveIndex(fallen));

		walk(fallen.dx(1));
		progress.clicked(0);
		assertEquals(1, next());
		walk(fallen.dx(2));
		animate(fallen.dx(3));
		assertEquals(1, next());
		assertEquals(-1, progress.liveIndex(fallen.dx(3)));
	}

	@Test
	public void resumesPartWayRound()
	{
		progress.resumeAfter(0);
		walk(A.dy(4));
		assertEquals(1, next());
		assertEquals(1, progress.liveIndex(A.dy(4)));

		progress.clicked(1);
		assertEquals(2, next());
		walk(A.dy(5));
		animate(A.dy(5));
		assertEquals(2, next());
		assertEquals(-1, progress.liveIndex(A.dy(5)));
	}

	@Test
	public void awayFromALapOnlyTheFirstObstacleShows()
	{
		walk(C.dx(5));
		assertFalse(progress.showsWholeCourse());

		progress.clicked(0);
		assertTrue(progress.showsWholeCourse());
		progress.clicked(-1);
		assertFalse(progress.showsWholeCourse());
	}

	@Test
	public void wholeCourseShowsOnALapAndForAMinuteAfterTheNextClick()
	{
		progress.resumeAfter(1);
		walk(B.dx(1));
		assertTrue(progress.showsWholeCourse());

		// Gone AFK on landing.
		land(C);
		walkFor(500, C);
		assertTrue(progress.showsWholeCourse());

		progress.clicked(-1);
		walkFor(99, C.dx(1));
		assertTrue(progress.showsWholeCourse());
		walk(C.dx(1));
		assertFalse(progress.showsWholeCourse());
	}

	@Test
	public void wholeCourseShowsAfterAFallUntilAMinuteAfterTheNextClick()
	{
		progress.resumeAfter(1);
		walk(B.dx(1));
		progress.clicked(2);
		progress.fell();
		walkFor(500, C.dx(5));
		assertTrue(progress.showsWholeCourse());

		progress.clicked(-1);
		walkFor(100, C.dx(5));
		assertFalse(progress.showsWholeCourse());
	}

	@Test
	public void nextIsReadyOnTheXpDropOfTheObstacleThatLandedYou()
	{
		walk(C);
		progress.clicked(0);
		animate(C.dx(1));
		assertFalse(progress.nextBecameReady());

		// The animation may still be finishing.
		land(A);
		assertTrue(progress.nextBecameReady());
		animate(A);
		assertFalse(progress.nextBecameReady());
		walk(A);
		assertFalse(progress.nextBecameReady());
	}

	@Test
	public void nextIsReadyOnTheXpDropWhenTheAnimationHasAlreadyEnded()
	{
		walk(C);
		progress.clicked(0);
		animate(C.dx(1));
		progress.xpDrop();
		walk(A);
		assertTrue(progress.nextBecameReady());
	}

	@Test
	public void clickingOnTheXpDropIsNotIdle()
	{
		walk(C);
		progress.clicked(0);
		animate(C.dx(1));
		progress.xpDrop();
		progress.clicked(1);
		animate(A);
		assertFalse(progress.nextBecameReady());
		walk(A);
		assertFalse(progress.nextBecameReady());

		// A walk elsewhere is acting too.
		animate(A.dy(1));
		progress.xpDrop();
		progress.clicked(-1);
		animate(B);
		assertFalse(progress.nextBecameReady());
		walk(B);
		assertFalse(progress.nextBecameReady());

		// Though the next landing is idle again.
		progress.clicked(2);
		animate(B.dx(1));
		land(C);
		assertTrue(progress.nextBecameReady());
	}

	@Test
	public void clickTheGameIgnoredMidObstacleLeavesYouIdle()
	{
		walk(C);
		progress.clicked(0);
		animate(C.dx(1));
		progress.clicked(1);
		land(A);
		assertTrue(progress.nextBecameReady());
	}

	@Test
	public void nextIsReadyOnTheFall()
	{
		walk(C);
		land(A);
		walk(A);
		progress.clicked(1);
		animate(A.dy(1));

		WorldPoint fallen = new WorldPoint(5, 5, 0);
		progress.fell();
		animate(fallen);
		assertTrue(progress.nextBecameReady());
		walk(fallen);
		assertFalse(progress.nextBecameReady());

		// Unless clicked on before the tick.
		progress.clicked(0);
		animate(fallen.dx(1));
		progress.fell();
		progress.clicked(-1);
		animate(fallen);
		assertFalse(progress.nextBecameReady());
	}

	@Test
	public void standingAboutIsNotIdle()
	{
		walk(C);
		assertFalse(progress.nextBecameReady());
		walk(C.dx(1));
		assertFalse(progress.nextBecameReady());

		// Nor is an animation that is not an obstacle ending.
		land(A);
		assertTrue(progress.nextBecameReady());
		walk(A);
		animate(A);
		walk(A);
		assertFalse(progress.nextBecameReady());
	}

	@Test
	public void resumingPartWayRoundIsNotIdle()
	{
		progress.resumeAfter(0);
		animate(A);
		assertFalse(progress.nextBecameReady());
		walk(A);
		assertFalse(progress.nextBecameReady());
	}

	private int next()
	{
		return progress.indexClicksAway(0);
	}

	private void walk(WorldPoint tile)
	{
		progress.tick(tile, false);
	}

	private void walkFor(int ticks, WorldPoint tile)
	{
		for (int tick = 0; tick < ticks; tick++)
		{
			walk(tile);
		}
	}

	private void animate(WorldPoint tile)
	{
		progress.tick(tile, true);
	}

	// The xp drops as the obstacle's animation finishes.
	private void land(WorldPoint tile)
	{
		progress.xpDrop();
		animate(tile);
	}
}

package com.rooftopobstaclepreview;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import org.junit.Test;

public class CourseTest
{
	@Test
	public void findsTheCourseThePlayerIsOnOrBeside()
	{
		assertEquals(Course.ARDOUGNE, Course.near(new WorldPoint(2671, 3299, 3)));
		assertEquals(Course.DRAYNOR, Course.near(new WorldPoint(3103, 3279, 0)));
		assertEquals(Course.SEERS, Course.near(new WorldPoint(2729, 3489, 0)));
		// The bank south of Ardougne market.
		assertNull(Course.near(new WorldPoint(2655, 3283, 0)));
	}

	@Test
	public void coursesDoNotOverlap()
	{
		for (Course course : Course.values())
		{
			for (RooftopObstacle obstacle : course.obstacles)
			{
				assertEquals(course, Course.near(obstacle.landing));
			}
		}
	}

	@Test
	public void eitherFaladorLedgeIsTheSameStep()
	{
		assertEquals(10, Course.FALADOR.indexOf(ObjectID.ROOFTOPS_FALADOR_LEDGE_3A));
		assertEquals(10, Course.FALADOR.indexOf(ObjectID.ROOFTOPS_FALADOR_LEDGE_3B));
		assertEquals(13, Course.FALADOR.obstacles.length);
	}

	@Test
	public void playerOnARoofLastCompletedTheObstacleThatLandsOnIt()
	{
		// Ardougne's first roof, from its far end.
		assertEquals(0, Course.ARDOUGNE.lastCompletedAt(new WorldPoint(2672, 3309, 3),
			(from, to) -> to.getX() >= 2671 && to.getX() <= 2672 && to.getY() >= 3299 && to.getY() <= 3309));
		// No obstacle lands on this plane.
		assertEquals(-1, Course.ARDOUGNE.lastCompletedAt(new WorldPoint(2660, 3305, 1), (from, to) -> true));
	}
}

